create extension if not exists "uuid-ossp"; -- ============================================================ -- CATCH-ALL MIGRATION: Creates all missing tables for Bateu -- Run this in Supabase SQL Editor -- Safe to run multiple times (uses IF NOT EXISTS / ADD COLUMN IF NOT EXISTS) -- ============================================================ -- ===================== 1. COMPANY BRANDING ===================== -- Drop old version if it exists without all columns, then recreate with full schema DROP TABLE IF EXISTS public.company_branding CASCADE; CREATE TABLE public.company_branding ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE UNIQUE, company_name TEXT, company_slogan TEXT, company_logo_url TEXT, primary_color TEXT DEFAULT '#fbbf24', secondary_color TEXT DEFAULT '#3b82f6', accent_color TEXT DEFAULT '#8b5cf6', background_color TEXT DEFAULT '#0a0e17', text_color TEXT DEFAULT '#ffffff', background_image_url TEXT, is_active BOOLEAN DEFAULT true, enabled BOOLEAN DEFAULT true, -- used by useGameBranding niche TEXT DEFAULT 'entertainment', hero_title TEXT, hero_subtitle TEXT, hero_cta_text TEXT DEFAULT 'Começar a Jogar', hero_cta_link TEXT DEFAULT '/lives', about_text TEXT, social_links JSONB DEFAULT '{}'::jsonb, homepage_layout TEXT DEFAULT 'showcase', featured_badge TEXT, show_leaderboard BOOLEAN DEFAULT true, show_games BOOLEAN DEFAULT true, show_lives BOOLEAN DEFAULT true, show_stats BOOLEAN DEFAULT true, custom_css TEXT, overlay_style TEXT DEFAULT 'modern', website_url TEXT, slug TEXT UNIQUE, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); CREATE INDEX IF NOT EXISTS idx_company_branding_user_id ON public.company_branding(user_id); ALTER TABLE public.company_branding ENABLE ROW LEVEL SECURITY; -- Owner full access CREATE POLICY "cb_owner_all" ON public.company_branding FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); -- Public read (needed for overlays and public profiles) CREATE POLICY "cb_public_read" ON public.company_branding FOR SELECT USING (true); GRANT ALL ON public.company_branding TO authenticated; GRANT SELECT ON public.company_branding TO anon; -- ===================== 2. LIVE GAME CONFIGS ===================== DROP TABLE IF EXISTS public.live_game_configs CASCADE; CREATE TABLE public.live_game_configs ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE UNIQUE, tap_duration INTEGER DEFAULT 5, quiz_questions INTEGER DEFAULT 5, quiz_time_per_q INTEGER DEFAULT 8, mystery_high REAL DEFAULT 0.25, mystery_low REAL DEFAULT 0.4, mystery_none REAL DEFAULT 0.35, board_game_timer INTEGER DEFAULT 30, allow_undo BOOLEAN DEFAULT false, scoring_system TEXT DEFAULT 'cumulative', point_multiplier REAL DEFAULT 1.0, allow_audience_challenges BOOLEAN DEFAULT true, challenge_cooldown INTEGER DEFAULT 30, enable_particles BOOLEAN DEFAULT true, enable_confetti BOOLEAN DEFAULT true, enable_glow_effects BOOLEAN DEFAULT true, animation_speed TEXT DEFAULT 'normal', is_active BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); CREATE INDEX IF NOT EXISTS idx_live_game_configs_user_id ON public.live_game_configs(user_id); ALTER TABLE public.live_game_configs ENABLE ROW LEVEL SECURITY; CREATE POLICY "lgc_owner_all" ON public.live_game_configs FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); GRANT ALL ON public.live_game_configs TO authenticated; -- ===================== 3. LIVE TEMPLATES ===================== CREATE TABLE IF NOT EXISTS public.live_templates ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, name TEXT NOT NULL DEFAULT 'Novo Template', description TEXT DEFAULT '', game_ids JSONB DEFAULT '[]'::jsonb, challenges JSONB DEFAULT '[]'::jsonb, rules JSONB DEFAULT '{}'::jsonb, branding JSONB DEFAULT '{}'::jsonb, is_active BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); CREATE INDEX IF NOT EXISTS idx_live_templates_user_id ON public.live_templates(user_id); ALTER TABLE public.live_templates ENABLE ROW LEVEL SECURITY; CREATE POLICY "lt_owner_all" ON public.live_templates FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); GRANT ALL ON public.live_templates TO authenticated; -- ===================== 4. LIVE NOTIFICATIONS ===================== CREATE TABLE IF NOT EXISTS public.live_notifications ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, body TEXT, data JSONB DEFAULT '{}'::jsonb, is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT now() ); CREATE INDEX IF NOT EXISTS idx_notifs_user ON public.live_notifications(user_id, created_at DESC); CREATE INDEX IF NOT EXISTS idx_notifs_unread ON public.live_notifications(user_id, is_read) WHERE NOT is_read; ALTER TABLE public.live_notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY "ln_users_read_own" ON public.live_notifications FOR SELECT USING (user_id = auth.uid()); CREATE POLICY "ln_users_update_own" ON public.live_notifications FOR UPDATE USING (user_id = auth.uid()); GRANT ALL ON public.live_notifications TO authenticated; -- ===================== 5. REGIONAL BRANDING ===================== -- Note: depends on regions table existing INSERT INTO public.regions (country_code, country_name, timezone, currency_code, language_code) VALUES ('MZ', 'Moçambique', 'Africa/Maputo', 'MZN', 'pt') ON CONFLICT (country_code) DO NOTHING; CREATE TABLE IF NOT EXISTS public.regional_branding ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), region_id UUID NOT NULL UNIQUE REFERENCES public.regions(id) ON DELETE CASCADE, primary_color VARCHAR(7) DEFAULT '#FF6B35', secondary_color VARCHAR(7) DEFAULT '#004E89', accent_color VARCHAR(7) DEFAULT '#F7B801', background_color VARCHAR(7) DEFAULT '#FFFFFF', text_color VARCHAR(7) DEFAULT '#000000', logo_url TEXT, banner_url TEXT, favicon_url TEXT, font_family VARCHAR(100) DEFAULT 'Inter, sans-serif', theme_name VARCHAR(100) DEFAULT 'default', custom_css TEXT, created_at TIMESTAMP DEFAULT now(), updated_at TIMESTAMP DEFAULT now() ); ALTER TABLE public.regional_branding ENABLE ROW LEVEL SECURITY; CREATE POLICY "rb_public_read" ON public.regional_branding FOR SELECT USING (true); GRANT SELECT ON public.regional_branding TO anon; GRANT ALL ON public.regional_branding TO authenticated; -- ===================== 6. REGIONAL SETTINGS ===================== CREATE TABLE IF NOT EXISTS public.regional_settings ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), region_id UUID NOT NULL UNIQUE REFERENCES public.regions(id) ON DELETE CASCADE, enable_spin_wheel BOOLEAN DEFAULT true, enable_millionaire_game BOOLEAN DEFAULT true, enable_challenge_games BOOLEAN DEFAULT true, enable_predictions BOOLEAN DEFAULT true, enable_live_games BOOLEAN DEFAULT true, max_concurrent_users INTEGER DEFAULT 10000, maintenance_mode BOOLEAN DEFAULT false, custom_features JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMP DEFAULT now(), updated_at TIMESTAMP DEFAULT now() ); ALTER TABLE public.regional_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY "rs_public_read" ON public.regional_settings FOR SELECT USING (true); GRANT SELECT ON public.regional_settings TO anon; GRANT ALL ON public.regional_settings TO authenticated; -- ===================== 7. NOTIFICATION PREFERENCES ON PROFILES ===================== DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'profiles' AND column_name = 'notification_preferences') THEN ALTER TABLE public.profiles ADD COLUMN notification_preferences JSONB DEFAULT '{}'::jsonb; END IF; END $$; -- ===================== 8. STORAGE BUCKET: company-branding-logos ===================== INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ( 'company-branding-logos', 'company-branding-logos', true, 5242880, -- 5MB ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/svg+xml'] ) ON CONFLICT (id) DO NOTHING; -- Storage policies for company-branding-logos CREATE POLICY "cbl_auth_upload" ON storage.objects FOR INSERT WITH CHECK ( bucket_id = 'company-branding-logos' AND auth.uid() IS NOT NULL AND (storage.foldername(name))[1] = auth.uid()::text ); CREATE POLICY "cbl_public_read" ON storage.objects FOR SELECT USING ( bucket_id = 'company-branding-logos' ); CREATE POLICY "cbl_owner_delete" ON storage.objects FOR DELETE USING ( bucket_id = 'company-branding-logos' AND auth.uid()::text = (storage.foldername(name))[1] ); -- ===================== 9. UPDATED_AT TRIGGER ===================== CREATE OR REPLACE FUNCTION public.update_updated_at_column() RETURNS TRIGGER AS $$ BEGIN NEW.updated_at = NOW(); RETURN NEW; END; $$ LANGUAGE plpgsql; DO $$ BEGIN CREATE TRIGGER update_company_branding_updated_at BEFORE UPDATE ON public.company_branding FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); EXCEPTION WHEN duplicate_object THEN NULL; END $$; DO $$ BEGIN CREATE TRIGGER update_live_game_configs_updated_at BEFORE UPDATE ON public.live_game_configs FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); EXCEPTION WHEN duplicate_object THEN NULL; END $$; DO $$ BEGIN CREATE TRIGGER update_live_templates_updated_at BEFORE UPDATE ON public.live_templates FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); EXCEPTION WHEN duplicate_object THEN NULL; END $$; -- ===================== 10. GRANT PERMISSIONS ===================== GRANT USAGE ON SCHEMA public TO authenticated; GRANT USAGE ON SCHEMA public TO anon;